243	function sheetXml({ cells, merges = [], cols = [], rowHeights = {} }) {
244	  const grouped = new Map();
245	  for (const [ref, c] of Object.entries(cells)) {
246	    const m = ref.match(/^([A-Z]+)(\d+)$/);
247	    const rowIdx = +m[2];
248	    if (!grouped.has(rowIdx)) grouped.set(rowIdx, []);
249	    grouped.get(rowIdx).push({ ref, ...c });
250	  }
251	  const rowXmls = [];
252	  for (const rowIdx of [...grouped.keys()].sort((a, b) => a - b)) {
253	    const cs = grouped.get(rowIdx).sort((a, b) => a.ref.localeCompare(b.ref, undefined, { numeric: true }));
254	    const ht = rowHeights[rowIdx] ? ` ht="${rowHeights[rowIdx]}" customHeight="1"` : '';
255	    const cellXmls = cs.map(c => {
256	      // Emit s="0" explicitly — style 0 (default) must not be dropped, else
257	      // a cell with style 0 and no value becomes a naked <c r="X"/> which
258	      // Excel flags as recoverable corruption.
259	      const hasStyle = (c.s !== undefined && c.s !== null);
260	      const styleAttr = hasStyle ? ` s="${c.s}"` : '';
261	      const isEmpty = (c.v === undefined || c.v === null || c.v === '');
262	      if (isEmpty) {
263	        // Skip entirely when neither style nor value — avoids <c r="X"/>.
264	        if (!hasStyle) return '';
265	        return `<c r="${c.ref}"${styleAttr}/>`;
266	      }
267	      if (typeof c.v === 'number') {
268	        return `<c r="${c.ref}"${styleAttr}><v>${c.v}</v></c>`;
269	      }
270	      return `<c r="${c.ref}"${styleAttr} t="inlineStr"><is><t xml:space="preserve">${esc(c.v)}</t></is></c>`;
271	    }).join('');
272	    rowXmls.push(`<row r="${rowIdx}"${ht}>${cellXmls}</row>`);
273	  }
274	  const colsXml = cols.length
275	    ? `<cols>${cols.map(c => `<col min="${c.min}" max="${c.max}" width="${c.width}" customWidth="1"/>`).join('')}</cols>`
276	    : '';
277	  const mergeXml = merges.length
278	    ? `<mergeCells count="${merges.length}">${merges.map(m => `<mergeCell ref="${m}"/>`).join('')}</mergeCells>`
279	    : '';
280	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
281	<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
282	${colsXml}
283	<sheetData>${rowXmls.join('')}</sheetData>
284	${mergeXml}
285	</worksheet>`;
