  // Title bar — merged A:Q, grey + bold + MEDIUM outer border (style 26).
  cells[R(r - 1, 0)] = { v: 'Parameters', s: 26 };
  for (let c = 1; c <= 16; c++) cells[R(r - 1, c)] = { s: 26 };
