  // Data rows — medium frame sides; last row inner cells get medium bottom (style 31).
  for (let idx = 0; idx < params.length; idx++) {
    const p = params[idx];
    const isLast = idx === params.length - 1;
    const innerStyle = isLast ? 31 : 5;  // 31 = thin-3-sides + medium-bottom
    cells[R(r - 1, 0)] = { s: 27 };     // medium left
    const vals = [p.field, p.type, p.required, p.defaultVal, p.description];
    vals.forEach((v, i) => {
      const [c0, c1] = COLS[i];
      cells[R(r - 1, c0)] = { v: v ?? '', s: innerStyle };
      for (let c = c0 + 1; c <= c1; c++) cells[R(r - 1, c)] = { s: innerStyle };
      merges.push(`${colLetter(c0)}${r}:${colLetter(c1)}${r}`);
    });
    cells[R(r - 1, 16)] = { s: 28 };    // medium right
    r++;
  }

  // Close outer frame corners: override last row col A/Q with medium BL/BR.
  const closeRow = r - 1;
  cells[R(closeRow - 1, 0)]  = { s: 29 };  // medium BL (left + bottom)
  cells[R(closeRow - 1, 16)] = { s: 30 };  // medium BR (right + bottom)

