    screenFrameRow(cells, r);  // col A / Q frame continuity
    const prefix = f.required ? '* ' : '  ';
    const label = `${prefix}${f.label || ''} (${f.name || ''})`;
    screenMerge(cells, merges, r, 1, 4, 7, label);                     // B:E label
