function renderAlvWireframe(cells, merges, rowHeights, startRow, spec) {
  const columns = spec.columns || [];
  const sampleRows = (spec.sampleRows || []).slice(0, Math.max(1, Math.min(spec.maxRows || 3, 5)));
  let r = startRow;

