### E. Replace the `textSheet(rows, opts = {})` function completely with this new implementation:
```js
function textSheet(rows, opts = {}) {
  const cells = {};
  const merges = [];
  const rowHeights = {};
  if (!rows || rows.length === 0) return { cells, merges, cols: [], rowHeights };

  const sectionTitle = opts.sectionTitle ?? '';
  const maxDataCols = Math.max(...rows.map(r => r.length));
  const explicitWidths = Array.isArray(opts.colWidths) ? opts.colWidths : null;

  // Auto-fit widths (CJK-aware) — used for row-height computation regardless of explicitWidths
  const autoCols = [];
  for (let c = 0; c < maxDataCols; c++) {
    let maxVw = 0;
    for (const row of rows) {
      const vw = visualWidth(row[c] ?? '');
      maxVw = Math.max(maxVw, Math.min(vw, WRAP_THRESHOLD));
    }
    autoCols.push({ width: Math.min(Math.max(maxVw + WIDTH_PADDING, WIDTH_MIN), WIDTH_MAX) });
  }

  // Emitted col widths: col A gutter (4.86) + data cols B onward
  const dataCols = explicitWidths || autoCols.map(c => c.width);
  const cols = [{ min: 1, max: 1, width: 4.86 }];
  {
    let i = 0;
    while (i < dataCols.length) {
      const w = dataCols[i];
      let j = i;
      while (j + 1 < dataCols.length && Math.abs(dataCols[j + 1] - w) < 0.01) j++;
      cols.push({ min: i + 2, max: j + 2, width: w });
      i = j + 1;
    }
    if (dataCols.length < maxDataCols) {
      cols.push({ min: dataCols.length + 2, max: maxDataCols + 1, width: WIDTH_MIN });
    }
  }

  // ── Row 1: padding row (ht=14.25) ────────────────────────────
  rowHeights[1] = 14.25;
  cells[R(0, 0)] = { s: TX.PAD };
  for (let c = 1; c <= maxDataCols; c++) cells[R(0, c)] = { s: TX.PAD };

  // ── Row 2: section title (ht=36) ─────────────────────────────
  rowHeights[2] = 36;
  cells[R(1, 0)] = { s: TX.PAD };
  if (maxDataCols >= 1) {
    cells[R(1, 1)] = { v: sectionTitle, s: TX.SEC_L };
    if (maxDataCols >= 2) {
      for (let c = 2; c < maxDataCols; c++) cells[R(1, c)] = { s: TX.SEC_M };
      cells[R(1, maxDataCols)] = { s: TX.SEC_R };
    }
  }

  // ── Row 3: spacer (ht=22.5) ──────────────────────────────────
  rowHeights[3] = 22.5;
  cells[R(2, 0)] = { s: TX.PAD };

  // ── Row 4: column headers (ht=22.5) ──────────────────────────
  rowHeights[4] = 22.5;
  if (rows.length > 0) {
    rows[0].forEach((val, cIdx) => {
      const isFirst = cIdx === 0;
      const isLast = cIdx === rows[0].length - 1;
      const style = isFirst ? TX.HDR_FIRST : (isLast ? TX.HDR_LAST : TX.HDR_MID);
      cells[R(3, cIdx + 1)] = { v: val, s: style };
    });
  }

  // ── Rows 5+: data rows ────────────────────────────────────────
  const dataRows = rows.slice(1);
  dataRows.forEach((row, rIdx) => {
    const actualRow = rIdx + 4; // 0-indexed: 4 preamble rows consumed, data at index 4, 5, ...
    const isLastRow = rIdx === dataRows.length - 1;
    let maxLines = 1;

    row.forEach((val, cIdx) => {
      const isFirstCol = cIdx === 0;
      const isLastCol = cIdx === row.length - 1;
      const vw = visualWidth(val ?? '');
      const isLong = vw > WRAP_THRESHOLD;
      const usable = Math.max(1, (autoCols[cIdx]?.width ?? WIDTH_MIN) - WIDTH_PADDING);

      let style;
      if (isLastRow) {
        style = isFirstCol ? TX.L_FIRST
               : isLastCol ? (isLong ? TX.L_LAST_W : TX.L_LAST)
               : (isLong ? TX.L_MID_W : TX.L_MID);
      } else {
        style = isFirstCol ? TX.D_FIRST
               : isLastCol ? (isLong ? TX.D_LAST_W : TX.D_LAST)
               : (isLong ? TX.D_MID_W : TX.D_MID);
      }
      cells[R(actualRow, cIdx + 1)] = { v: val ?? '', s: style };

      if (isLong) {
        const lines = Math.ceil(vw / usable);
        if (lines > maxLines) maxLines = lines;
      }
    });

    if (maxLines > 1) {
      rowHeights[actualRow + 1] = rowHeightForLines(Math.max(2, maxLines));
    }
  });

  return { cells, merges, cols, rowHeights };
}
```

