// textSheet(rows, opts) — produces the 양식예시.xlsx layout:
//   • Row 1: padding (ht=14.25) — col A=s=PAD_A, data cols=s=PAD_A
//   • Row 2: section title (ht=36) — B2:lastDataCol merged, B2=SEC_TITLE (Noto SK 15 bold + gray + L+T+B med blue),
//            middle cells=SEC_MID (T+B med blue), last data col=SEC_CAP (R+T+B med blue)
//   • Row 3: spacer (ht=22.5) — all PAD_A/SEC_DIV
//   • Row 4: column headers (ht=22.5) — first=HDR_FIRST (bold blue + light blue + L-med+R-dot+T-med+B-dot),
//            middle=HDR_MID (bold blue + light blue + L-thin+T-thin+B-dot), last=HDR_LAST (italic + L-dot+R-med+T-med+B-dot)
//   • Rows 5..N+4: data rows — first=D_FIRST (italic + L-med+B-dot+R-dot+T-dot), middle=D_MID (all dotted),
//                  last=D_LAST or D_LAST_W (regular + L-dot+R-med+T-dot+B-dot)
//   • Row N+4 (last data row): L_FIRST/L_MID/L_LAST or L_LAST_W — closes the table with B-med blue
//
// opts:
//   colWidths     — array of explicit data-column widths (in xlsx col-width units)
//   sectionTitle  — string for B2 (defaults to '' if not provided; build() passes opts.name)
//   gutterWidth   — col A gutter width (default 4.86 from template Overview sheet)
function textSheet(rows, opts = {}) {
  const cells = {};
  const merges = [];
  const rowHeights = {};
  if (!rows || rows.length === 0) return { cells, merges, cols: [], rowHeights };

  const sectionTitle = opts.sectionTitle ?? '';
  const gutterWidth = opts.gutterWidth ?? 4.86;
  const maxDataCols = Math.max(...rows.map(r => r.length));
  const explicitWidths = Array.isArray(opts.colWidths) ? opts.colWidths : null;

  // Auto-fit widths (CJK-aware) — drive row-height calculations even when explicit
  // widths are used so wrap cadence matches the reference layout.
  const autoCols = [];
  for (let c = 0; c < maxDataCols; c++) {
    let maxVw = 0;
    for (const row of rows) {
      const vw = visualWidth(row[c] ?? '');
      maxVw = Math.max(maxVw, Math.min(vw, WRAP_THRESHOLD));
    }
    const width = Math.min(Math.max(maxVw + WIDTH_PADDING, WIDTH_MIN), WIDTH_MAX);
    autoCols.push({ width });
  }

  // Emitted col widths: col A gutter (default 4.86) + data cols B onward.
  const dataWidths = explicitWidths || autoCols.map(c => c.width);
  const cols = [{ min: 1, max: 1, width: gutterWidth }];
  {
    let i = 0;
    while (i < dataWidths.length) {
      const w = dataWidths[i];
      let j = i;
      while (j + 1 < dataWidths.length && Math.abs(dataWidths[j + 1] - w) < 0.01) j++;
      cols.push({ min: i + 2, max: j + 2, width: w });
      i = j + 1;
    }
    if (dataWidths.length < maxDataCols) {
      cols.push({ min: dataWidths.length + 2, max: maxDataCols + 1, width: WIDTH_MIN });
    }
  }

  // ── Row 1: padding (ht=14.25) ───────────────────────────────────────
  rowHeights[1] = 14.25;
  cells[R(0, 0)] = { s: TX.PAD_A };
  for (let c = 1; c <= maxDataCols; c++) cells[R(0, c)] = { s: TX.PAD_A };

  // ── Row 2: section title (ht=36) ─────────────────────────────────────
  // Layout (template 양식예시.xlsx):
  //   A2 = PAD_A (gutter)
  //   B2 = SEC_TITLE with section title text (L+T+B med-blue, gray fill, Noto SK 15 bold center)
  //   C2..(lastDataCol-1) = SEC_MID (T+B med-blue, empty font) — middle span
  //   lastDataCol = SEC_CAP (R+T+B med-blue, empty font) — right cap
  //   Merge: B2:{lastDataCol}2 so the title text spans the full data area
  rowHeights[2] = 36;
  cells[R(1, 0)] = { s: TX.PAD_A };
  if (maxDataCols >= 1) {
    cells[R(1, 1)] = { v: sectionTitle, s: TX.SEC_TITLE };
    if (maxDataCols >= 2) {
      for (let c = 2; c < maxDataCols; c++) cells[R(1, c)] = { s: TX.SEC_MID };
      cells[R(1, maxDataCols)] = { s: TX.SEC_CAP };
      merges.push(`B2:${colLetter(maxDataCols)}2`);
    }
  }

  // ── Row 3: spacer (ht=22.5) ─────────────────────────────────────────
  rowHeights[3] = 22.5;
  cells[R(2, 0)] = { s: TX.PAD_A };
  for (let c = 1; c <= maxDataCols; c++) cells[R(2, c)] = { s: TX.SEC_DIV };

  // ── Row 4: column headers (ht=22.5) ─────────────────────────────────
  rowHeights[4] = 22.5;
  cells[R(3, 0)] = { s: TX.PAD_A };
  const headers = rows[0];
  headers.forEach((val, cIdx) => {
    const isFirst = cIdx === 0;
    const isLast = cIdx === headers.length - 1;
    const style = isFirst ? TX.HDR_FIRST : (isLast ? TX.HDR_LAST : TX.HDR_MID);
    cells[R(3, cIdx + 1)] = { v: val, s: style };
  });

  // ── Rows 5+: data rows ────────────────────────────────────────────────
  const dataRows = rows.slice(1);
  const is2Col = maxDataCols === 2;
  dataRows.forEach((row, rIdx) => {
    const xlsRow = rIdx + 4; // 0-indexed row offset (4 preamble rows already written)
    const isLastRow = rIdx === dataRows.length - 1;
    let maxLines = 1;
    let anyLong = false;

    cells[R(xlsRow, 0)] = { s: TX.PAD_A_DATA }; // col A gutter for data area

    row.forEach((val, cIdx) => {
      const isFirstCol = cIdx === 0;
      const isLastCol = cIdx === row.length - 1;
      const vw = visualWidth(val ?? '');
      const isLong = vw > WRAP_THRESHOLD;
      const usable = Math.max(1, (autoCols[cIdx]?.width ?? WIDTH_MIN) - WIDTH_PADDING);

      let style;
      if (isLastRow) {
        // Last data row — close the table with B-med blue
        if (is2Col) {
          style = isFirstCol ? TX.L_FIRST_2C : (isLong ? TX.L_LAST_W : TX.L_LAST);
        } else {
          style = isFirstCol ? TX.L_FIRST
                 : isLastCol ? (isLong ? TX.L_LAST_W : TX.L_LAST)
                 : (isLong ? TX.L_MID_W : TX.L_MID);
        }
      } else {
        // Regular data row
        if (is2Col) {
          style = isFirstCol ? TX.D_FIRST_2C : (isLong ? TX.D_LAST_W : TX.D_LAST);
        } else {
          style = isFirstCol ? TX.D_FIRST
                 : isLastCol ? (isLong ? TX.D_LAST_W : TX.D_LAST)
                 : (isLong ? TX.D_MID_W : TX.D_MID);
        }
      }
      cells[R(xlsRow, cIdx + 1)] = { v: val ?? '', s: style };

      if (isLong) {
        anyLong = true;
        const lines = Math.ceil(vw / usable);
        if (lines > maxLines) maxLines = lines;
      }
    });

    if (anyLong) {
      const lines = Math.max(2, maxLines);
      rowHeights[xlsRow + 1] = rowHeightForLines(lines);
    }
  });

  return { cells, merges, cols, rowHeights };
}

