695	//   Processing Logic sheet automatically when PROCESS_FLOW is non-empty.
696	//
697	// Layout (3-col span = matches the ABAP Logic sheet's #/Event/Step grid):
698	//   row N+1   blank spacer
699	//   row N+2   "Process Flow Chart" heading       (style 17, A:C merged)
700	//   row N+3   first node (box / decision)        (A:C merged, ↓ stacked)
701	//   row N+4   "↓"                                 (style 25, no border)
702	//   row N+5   next node ...
703	//
704	// Node convention (each PROCESS_FLOW item is a single string):
705	//   · Plain text                → bordered box (style 21)
706	//   · Prefix '?' → decision       → yellow box (style 20), '?' stripped, '◇ ' added
707	//   · Prefix '!' → terminal/exit  → bordered box, '■ ' added (END / RETURN /
708	//                                   LEAVE LIST-PROCESSING markers)
709	//
710	// Decision branches that need a separate side-arm row are described inside
711	// the decision string itself with " → " (e.g. "? gt_result IS INITIAL → MESSAGE + LEAVE")
712	// — the renderer keeps everything on one row so the chart stays compact in
713	// a 3-column grid. For programs that need true two-branch fan-out, drivers
714	// can render the branch as the next node prefixed with "└─ " or similar.
715	// =============================================================
716	function appendProcessFlow(payload, items, opts = {}) {
717	  if (!Array.isArray(items) || items.length === 0) return payload;
718	  const { cells, merges, rowHeights, cols } = payload;
719	  const heading = opts.heading || 'Process Flow Chart';
720	  const colSpan = Math.max(1, Math.min(3, cols.length || 3));
721	  const lastCol = colLetter(colSpan - 1);
722	
723	  // Find next free row by scanning current cells.
724	  let maxRow = 0;
725	  for (const ref of Object.keys(cells)) {
726	    const m = /^([A-Z]+)(\d+)$/.exec(ref);
727	    if (m) maxRow = Math.max(maxRow, +m[2]);
728	  }
729	
730	  let r = maxRow + 2; // 1 blank spacer row between table and heading
731	
732	  // Heading row — style 17 (grey + bold + all borders).
733	  cells[R(r - 1, 0)] = { v: heading, s: 17 };
734	  for (let c = 1; c < colSpan; c++) cells[R(r - 1, c)] = { s: 17 };
735	  if (colSpan > 1) merges.push(`A${r}:${lastCol}${r}`);
736	  rowHeights[r] = 22;
