let driverSrc = tpl;

function setConst(src, name, value) {
  // Replace `^const NAME = ...;` at start-of-line (skip commented-out examples).
  // Two patterns: (1) single-line `const NAME = expr;`  (2) multi-line with array/object literal.
  // We anchor with `\n` before `const` to skip comment-prefixed `//   const NAME = ...` examples.
  // Match up to the first `;` that is followed by an EOL — but stop before another `const ` line.
  const escName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(`(\\nconst\\s+${escName}\\s*=)[^\\n]*(?:\\n(?!const\\s)[^\\n]*)*?;\\s*\\n`, '');
  if (!re.test(src)) {
    console.warn('[setConst] pattern not found for:', name);
    return src;
  }
  return src.replace(re, `\nconst ${name} = ${value};\n`);
}

