export function renderProcessFlowSVG(items = [], { lang = 'ko', heading = 'Process Flow Chart', width = 700 } = {}) {
  const BOX_W = 560;
  const BOX_H = 38;
  const DIAMOND_H = 52;
  const TERM_H = 36;
  const ARROW_H = 28;
  const PAD_TOP = 44;
  const PAD_BOT = 24;
  const LEFT = (width - BOX_W) / 2;
  const BLUE = '#0A4F8C';
  const YELLOW = '#FFFDE7';
  const GRAY_FILL = '#EFEFEF';

  let y = PAD_TOP;
  const parts = [];

  // Heading row
  parts.push(`<text x="${width / 2}" y="${y - 10}" text-anchor="middle" font-size="14" font-weight="700" fill="${BLUE}">${xml(heading)}</text>`);

  items.forEach((raw, i) => {
    const txt = String(raw ?? '');
    const isDecision = /^\?\s*/.test(txt);
    const isTerminal = /^!\s*/.test(txt);
    const label = isDecision ? txt.replace(/^\?\s*/, '')
                 : isTerminal ? txt.replace(/^!\s*/, '')
                 : txt;

    if (isDecision) {
      // Diamond shape
      const cx = width / 2, cy = y + DIAMOND_H / 2;
      const dx = BOX_W / 2, dy = DIAMOND_H / 2;
      parts.push(`<polygon points="${cx},${cy - dy} ${cx + dx},${cy} ${cx},${cy + dy} ${cx - dx},${cy}" fill="${YELLOW}" stroke="${BLUE}" stroke-width="1.5"/>`);
      const labelLines = wrapTextSvg(label, Math.floor(BOX_W * 0.7 / 7));
      labelLines.forEach((line, li) => {
        const textY = cy - ((labelLines.length - 1) * 8) + li * 16;
        parts.push(`<text x="${cx}" y="${textY}" text-anchor="middle" font-size="12" fill="#333">${xml(line)}</text>`);
      });
      y += DIAMOND_H;
    } else if (isTerminal) {
      // Rounded rectangle (pill)
      parts.push(`<rect x="${LEFT}" y="${y}" width="${BOX_W}" height="${TERM_H}" rx="18" fill="${GRAY_FILL}" stroke="${BLUE}" stroke-width="1.5"/>`);
      parts.push(`<text x="${width / 2}" y="${y + TERM_H / 2 + 4}" text-anchor="middle" font-size="12" font-weight="700" fill="${BLUE}">${xml(label)}</text>`);
      y += TERM_H;
    } else {
      // Process rectangle
      parts.push(`<rect x="${LEFT}" y="${y}" width="${BOX_W}" height="${BOX_H}" fill="#FFFFFF" stroke="${BLUE}" stroke-width="1.5"/>`);
      const labelLines = wrapTextSvg(label, Math.floor(BOX_W * 0.9 / 7));
      labelLines.forEach((line, li) => {
        const textY = y + BOX_H / 2 - ((labelLines.length - 1) * 8) + li * 16 + 4;
        parts.push(`<text x="${width / 2}" y="${textY}" text-anchor="middle" font-size="12" fill="#222">${xml(line)}</text>`);
      });
      y += BOX_H;
    }

    // Arrow between items
    if (i < items.length - 1) {
      const arrowX = width / 2;
      parts.push(`<line x1="${arrowX}" y1="${y}" x2="${arrowX}" y2="${y + ARROW_H - 6}" stroke="${BLUE}" stroke-width="1.5"/>`);
      parts.push(`<polygon points="${arrowX - 6},${y + ARROW_H - 8} ${arrowX + 6},${y + ARROW_H - 8} ${arrowX},${y + ARROW_H}" fill="${BLUE}"/>`);
      y += ARROW_H;
    }
  });

  const totalH = y + PAD_BOT;
  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${Math.round(width * RENDER_SCALE)}" height="${Math.round(totalH * RENDER_SCALE)}" viewBox="0 0 ${width} ${totalH}" font-family="Arial,sans-serif" font-size="12">
<rect width="${width}" height="${totalH}" fill="#FFF"/>
${parts.join('\n')}
</svg>`;
}

export function processFlowMetrics(items = [], { width = 700 } = {}) {
  const BOX_H = 38, DIAMOND_H = 52, TERM_H = 36, ARROW_H = 28, PAD_TOP = 44, PAD_BOT = 24;
  let h = PAD_TOP;
  items.forEach((raw, i) => {
    const txt = String(raw ?? '');
    if (/^\?\s*/.test(txt)) h += DIAMOND_H;
    else if (/^!\s*/.test(txt)) h += TERM_H;
    else h += BOX_H;
    if (i < items.length - 1) h += ARROW_H;
  });
  h += PAD_BOT;
  return { width: Math.round(width * RENDER_SCALE), height: Math.round(h * RENDER_SCALE) };
}

