    } else {
      if (cur) lines.push(cur);
      cur = tok.replace(/^\s+/, ''); // drop leading whitespace on new line
      curW = [...cur].reduce((s, ch) => s + charWidth(ch), 0);
    }
  }
  if (cur) lines.push(cur);
  return lines.length ? lines : [''];
}

