// Substitute the TODO constants in the template
let driverSrc = tpl;

function setConst(src, name, value) {
  // Find the line `^const NAME = ...` (skipping commented examples).
  // Then scan forward to find the matching `;` at end-of-statement —
  // balancing brackets so JSON literals with `]` or `}` work.
  const lines = src.split('\n');
  let startLine = -1;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].match(new RegExp(`^const\\s+${name.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\$&')}\\s*=`))) {
      startLine = i;
      break;
    }
  }
  if (startLine === -1) {
    console.warn('[setConst] pattern not found for:', name);
    return src;
  }
  // Find end of statement by tracking bracket depth on the joined text from startLine.
  let depth = 0;
  let endLine = -1;
  for (let i = startLine; i < lines.length; i++) {
    const line = lines[i];
    for (const ch of line) {
      if (ch === '[' || ch === '{' || ch === '(') depth++;
      else if (ch === ']' || ch === '}' || ch === ')') depth--;
    }
    if (depth === 0 && line.includes(';')) { endLine = i; break; }
  }
  if (endLine === -1) {
    console.warn('[setConst] no terminating `;` for:', name);
    return src;
  }
  const newLine = `const ${name} = ${value};`;
  return [
    ...lines.slice(0, startLine),
    newLine,
    ...lines.slice(endLine + 1),
  ].join('\n');
}

driverSrc = setConst(driverSrc, 'SHEETS_DATA', JSON.stringify(SHEETS_DATA));
driverSrc = setConst(driverSrc, 'PROCESS_FLOW', JSON.stringify(PROCESS_FLOW));
driverSrc = setConst(driverSrc, 'PROCESS_FLOW_SHEET', JSON.stringify('Processing Logic'));
driverSrc = setConst(driverSrc, 'PROCESS_FLOW_HEADING', JSON.stringify('프로세스 흐름도'));
driverSrc = setConst(driverSrc, 'OUT_PATH', JSON.stringify(OUT_PATH));
driverSrc = setConst(driverSrc, 'INPUTS_SHEET_NAME', JSON.stringify('Inputs & Screens'));
driverSrc = setConst(driverSrc, 'SPEC_LANG', JSON.stringify('ko'));
driverSrc = setConst(driverSrc, 'SHEET_TITLE', JSON.stringify('Inputs & Screens · ZMMR1001'));
driverSrc = setConst(driverSrc, 'CLEANUP_AFTER_BUILD', 'false');

// Write temp driver and run it
const tmpDir = mkdtempSync(join(tmpdir(), 'sc4sap-zmmr1001-'));
const tmpDriver = join(tmpDir, 'driver.mjs');
writeFileSync(tmpDriver, driverSrc, 'utf8');
console.log('Temp driver:', tmpDriver);

try {
  await import(pathToFileURL(tmpDriver).href);
  console.log('SUCCESS — xlsx written to:', OUT_PATH);
} catch (err) {
  console.error('Driver failed:', err);
  process.exit(1);
} finally {
  // keep temp dir for debugging if needed
  try { rmSync(tmpDir, { recursive: true, force: true }); } catch { /* ignore */ }
}

