function paramsBlock(cells, merges, rowHeights, startRow, params = [], opts = {}) {
  const COLS = [[1, 3], [4, 5], [6, 7], [8, 10], [11, 15]]; // B:D E:F G:H I:K L:P
  const HEADERS = opts.headers || ['Field', 'Type', 'Required', 'Default', 'Description'];
  const titleText = opts.title || 'Parameters';
  let r = startRow;

  // v11: title / header / data rows all use the SAME TX.* styles that textSheet
  // uses, so the params block reads visually identical to a textSheet data table.
  // Style mapping per row:
  //   • Title bar (1 row, merged B..P):
  //       A = TX.PAD_A
  //       B..O = TX.SEC_TITLE / TX.SEC_MID
  //       P = TX.SEC_CAP
  //       Q = TX.PAD_A
  //   • Header row:
  //       A = TX.PAD_A
  //       B:D = TX.HDR_FIRST | E:F,G:H,I:K = TX.HDR_MID | L:P = TX.HDR_LAST
  //       Q = TX.PAD_A
  //   • Data row (non-last):
  //       A = TX.PAD_A_DATA
  //       B:D = TX.D_FIRST | E:F,G:H,I:K = TX.D_MID | L:P = TX.D_LAST(W)
  //       Q = TX.PAD_A
  //   • Last data row:  same shape with L_* styles (closes the table with B-med blue)

  // ── Title row ─────────────────────────────────────────────────
  cells[R(r - 1, 0)] = { s: TX.PAD_A };
  cells[R(r - 1, 1)] = { v: titleText, s: TX.SEC_TITLE };
  for (let c = 2; c < 15; c++) cells[R(r - 1, c)] = { s: TX.SEC_MID };
  cells[R(r - 1, 15)] = { s: TX.SEC_CAP };
  cells[R(r - 1, 16)] = { s: TX.PAD_A };
  merges.push(`B${r}:P${r}`);
  rowHeights[r] = 36;
  r++;

  // ── Header row ────────────────────────────────────────────────
  cells[R(r - 1, 0)] = { s: TX.PAD_A };
  HEADERS.forEach((h, i) => {
    const [c0, c1] = COLS[i];
    const isFirst = i === 0;
    const isLast  = i === HEADERS.length - 1;
    const style = isFirst ? TX.HDR_FIRST : (isLast ? TX.HDR_LAST : TX.HDR_MID);
    cells[R(r - 1, c0)] = { v: h, s: style };
    for (let c = c0 + 1; c <= c1; c++) cells[R(r - 1, c)] = { s: style };
    merges.push(`${colLetter(c0)}${r}:${colLetter(c1)}${r}`);
  });
  cells[R(r - 1, 16)] = { s: TX.PAD_A };
  rowHeights[r] = 22.5;
  r++;

  // ── Data rows ─────────────────────────────────────────────────
  for (let idx = 0; idx < params.length; idx++) {
    const p = params[idx];
    const isLastRow = idx === params.length - 1;
    cells[R(r - 1, 0)] = { s: TX.PAD_A_DATA };
    const vals = [p.field, p.type, p.required, p.defaultVal, p.description];
    let maxLines = 1;
    vals.forEach((v, i) => {
      const [c0, c1] = COLS[i];
      const isFirstCol = i === 0;
      const isLastCol  = i === vals.length - 1;
      const vw = visualWidth(v);
      const isLong = vw > WRAP_THRESHOLD;
      let style;
      if (isLastRow) {
        style = isFirstCol ? TX.L_FIRST
              : isLastCol  ? (isLong ? TX.L_LAST_W : TX.L_LAST)
              :              (isLong ? TX.L_MID_W  : TX.L_MID);
      } else {
        style = isFirstCol ? TX.D_FIRST
              : isLastCol  ? (isLong ? TX.D_LAST_W : TX.D_LAST)
              :              (isLong ? TX.D_MID_W  : TX.D_MID);
      }
      cells[R(r - 1, c0)] = { v: v ?? '', s: style };
      for (let c = c0 + 1; c <= c1; c++) cells[R(r - 1, c)] = { s: style };
      merges.push(`${colLetter(c0)}${r}:${colLetter(c1)}${r}`);
      if (isLong) {
        // Group-cell column count for height estimation.
        const groupCells = c1 - c0 + 1;
        const groupApproxWidth = (i === 4) ? 5 * 14 : groupCells * 14; // L:P widens
        const usable = Math.max(1, groupApproxWidth - WIDTH_PADDING);
        const lines = Math.ceil(vw / usable);
        if (lines > maxLines) maxLines = lines;
      }
    });
    cells[R(r - 1, 16)] = { s: TX.PAD_A };
    if (maxLines > 1) rowHeights[r] = rowHeightForLines(Math.max(2, maxLines));
    r++;
  }

  return r;
}

