// Strategy: clone the source xlsx byte-for-byte, only swap sharedStrings.xml
// so all styles, borders, fonts, column widths, row heights, drawings stay intact.

import { readFileSync, writeFileSync } from 'node:fs';
import { deflateRawSync, inflateRawSync } from 'node:zlib';

