// --- Translate sharedStrings.xml ---
function translateSharedStrings(xml) {
  return xml.replace(/<t([^>]*)>([\s\S]*?)<\/t>/g, (m, attrs, body) => {
    const decoded = body.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
    const translated = TR[decoded];
    if (translated == null) {
      if (/[A-Za-z]/.test(decoded) && decoded.length > 1) {
        console.log('  · NO TRANSLATION:', JSON.stringify(decoded.slice(0, 80)));
      }
      return m;
    }
    const enc = translated.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
    const needsSpace = /^\s|\s$|\n/.test(translated);
    const newAttrs = needsSpace && !/xml:space/.test(attrs) ? ' xml:space="preserve"' + attrs : attrs;
    return `<t${newAttrs}>${enc}</t>`;
  });
}

const src = readFileSync(SRC);
const entries = unzipEntries(src);
console.log(`Read ${entries.length} entries from 양식예시.xlsx`);

for (const e of entries) {
  if (e.name === 'xl/sharedStrings.xml') {
    const xml = e.data.toString('utf8');
    const newXml = translateSharedStrings(xml);
    e.data = Buffer.from(newXml, 'utf8');
    console.log('Translated xl/sharedStrings.xml');
  }
}

const out = zipFiles(entries);
writeFileSync(DST, out);
console.log(`✅ Wrote ${DST} (${out.length} bytes)`);

